N = "5-2"


def titulo():
    return t("The election process: parties, campaigns, and the Electoral College", "El proceso electoral: partidos, campañas y colegio electoral")


def graf_edad():
    spec = {"tipo": "barras", "xEtq": t("Age group", "Grupo de edad"), "yEtq": t("Percent who voted", "Porcentaje que votó"),
            "barras": [{"etq": t("18 to 24", "18 a 24"), "valor": 47.7, "txt": "47.7%"}, {"etq": t("25 to 44", "25 a 44"), "valor": 60.2, "txt": "60.2%"},
                       {"etq": t("45 to 64", "45 a 64"), "valor": 70.0, "txt": "70.0%"}, {"etq": t("65 and older", "65 o más"), "valor": 74.7, "txt": "74.7%"}]}
    return C.grafica(spec, C.describe(spec), ancho=560, alto=300, y0=0, y1=100)


def graf_estudios():
    spec = {"tipo": "barras", "xEtq": t("Highest level of education", "Nivel de estudios más alto"), "yEtq": t("Percent who voted", "Porcentaje que votó"),
            "barras": [{"etq": t("High school diploma", "Diploma de secundaria"), "valor": 52.5, "txt": "52.5%"}, {"etq": t("Bachelor’s degree", "Licenciatura"), "valor": 77.2, "txt": "77.2%"},
                       {"etq": t("Advanced degree", "Posgrado"), "valor": 82.5, "txt": "82.5%"}]}
    return C.grafica(spec, C.describe(spec), ancho=560, alto=300, y0=0, y1=100)


