def banco_colegio():
    D = [(t("A state has 4 representatives. How many electoral votes does it have?", "Un estado tiene 4 representantes. ¿Cuántos votos electorales tiene?"), ["6", "4", "5", "8"], t("4 representatives + 2 senators = 6.", "4 representantes + 2 senadores = 6.")),
         (t("Illinois has 17 representatives. How many electoral votes does it have?", "Illinois tiene 17 representantes. ¿Cuántos votos electorales tiene?"), ["19", "17", "18", "34"], t("17 + 2 = 19.", "17 + 2 = 19.")),
         (t("A state has 25 electoral votes. How many representatives does it have?", "Un estado tiene 25 votos electorales. ¿Cuántos representantes tiene?"), ["23", "25", "27", "24"], t("25 − 2 senators = 23.", "25 − 2 senadores = 23.")),
         (t("Candidate X wins a 12-vote state by 51% to 49%. How many of its electoral votes does Y get (winner-take-all)?", "La candidata X gana un estado de 12 votos por 51 % contra 49 %. ¿Cuántos de sus votos electorales recibe Y (todo para el ganador)?"), ["0", "6", "5", "12"], t("Winner takes all: Y gets none.", "Todo para el ganador: Y no recibe ninguno.")),
         (t("A candidate has 262 electoral votes. A state with 10 is still undecided. If she wins it, does she reach the presidency?", "Una candidata tiene 262 votos electorales. Falta un estado de 10. Si lo gana, ¿llega a la presidencia?"), [t("Yes: 272 is more than 270", "Sí: 272 es más que 270"), t("No: she needs 538", "No: necesita 538"), t("No: she needs 300", "No: necesita 300")], t("262 + 10 = 272 ≥ 270.", "262 + 10 = 272 ≥ 270.")),
         (t("State A: X wins 3,000,000 to 2,900,000 (8 electoral votes). State B: Y wins 4,000,000 to 1,000,000 (8 electoral votes). Who leads the popular vote?", "Estado A: X gana por 3,000,000 contra 2,900,000 (8 votos electorales). Estado B: Y gana por 4,000,000 contra 1,000,000 (8 votos electorales). ¿Quién va delante en voto popular?"),
          [t("Y, with 6,900,000 to 4,000,000", "Y, con 6,900,000 contra 4,000,000"), t("X, with 4,000,000 to 6,900,000", "X, con 4,000,000 contra 6,900,000"), t("They are tied", "Están empatados")], t("Y: 2,900,000 + 4,000,000; X: 3,000,000 + 1,000,000. Electoral votes are tied 8 to 8.", "Y: 2,900,000 + 4,000,000; X: 3,000,000 + 1,000,000. Los votos electorales empatan 8 a 8.")),
         (t("Where is winner-take-all written?", "¿Dónde está escrita la regla de todo para el ganador?"), [t("In each state’s laws", "En las leyes de cada estado"), t("In the Constitution", "En la Constitución"), t("In a Supreme Court decision", "En una sentencia del Tribunal Supremo")], t("Maine and Nebraska show that each state decides.", "Maine y Nebraska muestran que cada estado decide.")),
         (t("The National Popular Vote compact takes effect when its states reach…", "El pacto por el voto popular nacional entra en vigor cuando sus estados reúnen…"), [t("270 electoral votes", "270 votos electorales"), t("all 50 states", "los 50 estados"), t("a constitutional amendment", "una enmienda constitucional")], t("A majority of the 538; in 2026 it had 222.", "La mayoría de los 538; en 2026 tenía 222.")),
         ]
    return [{"enun": "<strong>" + s + "</strong>", "ops": ops, "ok": 0, "exp": e} for s, ops, e in D]


def casos_tecnicas():
    G = [t("Fear appeal", "Apelación al miedo"), t("Plain folks", "Gente corriente"), t("Testimonial", "Testimonio"), t("Loaded words", "Palabras cargadas"), t("Selective contrast", "Contraste selectivo")]
    PI = [t("Does it describe a vague danger if the other side wins?", "¿Describe un peligro vago si gana el otro?"), t("Does it present the candidate as one of us?", "¿Presenta al candidato como uno más?"),
          t("Does a well-known or likable person endorse, without reasons?", "¿Una persona conocida o simpática da su apoyo, sin razones?"), t("Do the words judge while seeming to describe?", "¿Las palabras valoran mientras aparentan describir?"),
          t("Does it put the best of one side next to the worst of the other?", "¿Pone lo mejor de uno al lado de lo peor del otro?")]
    def caso(tit, piezas):
        return {"titulo": tit, "intro": t("These campaign lines are invented. Name the main technique of each one.", "Estas frases de campaña son inventadas. Nombre la técnica principal de cada una."), "grupos": G, "etiqueta": t("Technique:", "Técnica:"),
                "piezas": [{"t": a, "v": v, "pista": PI[v]} for a, v in piezas]}
    return [
        caso(t("Set 1", "Serie 1"), [(t("“If he wins, your children’s future will be gone.”", "«Si gana él, el futuro de sus hijos habrá desaparecido»."), 0), (t("“I still shop at the same corner store where my mother shopped.”", "«Sigo comprando en la misma tienda de la esquina donde compraba mi madre»."), 1),
                                      (t("“As a nurse for thirty years, I’m voting for her.”", "«Como enfermera durante treinta años, voy a votar por ella»."), 2), (t("“Her reckless, job-killing scheme.”", "«Su plan temerario que destruye empleos»."), 3)]),
        caso(t("Set 2", "Serie 2"), [(t("“He created 4,000 jobs; she voted to close a plant.” (Both true, both chosen.)", "«Él creó 4,000 empleos; ella votó por cerrar una planta». (Las dos cosas ciertas, las dos elegidas)."), 4), (t("“A dangerous, extreme agenda.”", "«Una agenda peligrosa y extremista»."), 3),
                                      (t("“The champion coach says: she has my vote.”", "«El entrenador campeón dice: tiene mi voto»."), 2), (t("“They will take everything you worked for.”", "«Le quitarán todo aquello por lo que ha trabajado»."), 0)]),
        caso(t("Set 3", "Serie 3"), [(t("“I drive my own pickup to work, just like you.”", "«Voy al trabajo en mi propia camioneta, igual que usted»."), 1), (t("“Our record: lower crime. Their record: a scandal in 2019.”", "«Nuestro historial: menos delitos. El suyo: un escándalo en 2019»."), 4),
                                      (t("“A bold, common-sense leader.”", "«Un líder valiente y con sentido común»."), 3), (t("“Without us, the town will fall apart.”", "«Sin nosotros, el pueblo se vendrá abajo»."), 0)]),
    ]


def practica():
    A = {"en": ["stages", "electoral-college", "techniques"], "es": ["etapas", "colegio-electoral", "tecnicas"]}[C.L]
    mods = [
        (A[0], t("From candidacy to taking office", "De la candidatura a la toma de posesión"), C.orden("m1")),
        (A[1], t("The Electoral College, by the numbers", "El colegio electoral, en números"), C.om("m2", t("Remember: electoral votes = representatives + 2. Winner takes all. 270 wins.", "Recuerde: votos electorales = representantes + 2. Todo para el ganador. Con 270 se gana."))),
        (A[2], t("Name the technique", "Nombre la técnica"), C.clasifica("m3", t("Read each line and choose its main technique. If something is not right, the lines marked in yellow get a hint.", "Lea cada frase y elija su técnica principal. Si algo no está bien, las frases marcadas en amarillo reciben una pista."))),
    ]
    js = (C.js_datos("ETA", casos_orden()) + C.js_datos("COL", banco_colegio()) + C.js_datos("TEC", casos_tecnicas()) +
          'creaOrden("m1", ETA);\ncreaBanco("m2", COL);\ncreaClasifica("m3", TEC);\n')
    return C.pagina_practica(N, titulo(), t("Three activities · the order of the exercises changes every time · two tries in each one", "Tres actividades · el orden de los ejercicios cambia cada vez · dos intentos en cada uno"), mods, js)


if __name__ == "__main__":
    C.construye(N, leccion, practica)
